def source_arrays(example,row):
    import numpy as np
    from dataset import bridge_reverse_scan_gripper,rt1_relative_gripper_commands,euler_xyz_to_quaternion,rotation_vector_to_quaternion
    from oxe_source_semantics import command_features_before_rows
    f=example.features.feature;n=row['steps'];source=row['source']
    if source=='Bridge':
        state=values(f,'steps/observation/state',7,n)
        action=values(f,'steps/action',7,n)
        pos=state[:,:3];orientation=state[:,3:6]
        if not np.isfinite(pos).all() or not np.isfinite(orientation).all():raise ValueError('nonfinite_used_pose')
        for name,index in (('is_first',0),('is_last',n-1)):
            flags=list(f['steps/'+name].int64_list.value)
            if len(flags)!=n or any(x not in (0,1) for x in flags) or [i for i,x in enumerate(flags) if x]!=[index]:
                raise ValueError('bridge_invalid_RLDS_boundary')
        commands=action[:,6]
        if not np.isfinite(commands[:-1]).all():raise ValueError('nonfinite_used_command')
        labels=bridge_reverse_scan_gripper(commands[:-1])
        if not np.isin(labels,[0,1]).all():raise ValueError('bridge_unresolved_nonbinary_reverse_scan')
        features=command_features_before_rows('bridge',commands)
        quats=np.asarray([euler_xyz_to_quaternion(v) for v in orientation])
    elif source=='BC-Z':
        pos=values(f,'steps/observation/present/xyz',3,n)
        angles=values(f,'steps/observation/present/axis_angle',3,n)
        commands=values(f,'steps/action/future/target_close',10,n)
        # The current production parser validates the complete command table.
        if not np.isfinite(commands).all():raise ValueError('nonfinite_production_command_table')
        features=command_features_before_rows('bc_z',commands[:,0])
        if not np.isfinite(pos).all() or not np.isfinite(angles).all():raise ValueError('nonfinite_used_pose')
        quats=np.asarray([rotation_vector_to_quaternion(v) for v in angles])
    elif source=='Fractal':
        poses=values(f,'steps/observation/base_pose_tool_reached',7,n)
        commands=values(f,'steps/action/gripper_closedness_action',1,n)[:,0]
        pos=poses[:,:3];quats=poses[:,3:7]
        if not np.isfinite(poses).all():raise ValueError('nonfinite_used_pose')
        if np.any(np.linalg.norm(quats.astype(np.float64),axis=1)<1e-8):raise ValueError('missing_orientation_no_identity_substitution')
        rt1_relative_gripper_commands(commands) # Actual production target conversion.
        features=command_features_before_rows('fractal',commands)
    else:
        pos=values(f,'steps/observation/effector_translation',2,n)
        if not np.isfinite(pos).all():raise ValueError('nonfinite_used_planar_pose')
        features=np.zeros((n,2),np.float32);quats=None
    if quats is not None and (not np.isfinite(quats).all() or np.any(np.linalg.norm(quats.astype(np.float64),axis=1)<1e-8)):
        raise ValueError('invalid_converted_orientation')
    span=(pos.astype(np.float64).max(axis=0)-pos.astype(np.float64).min(axis=0))/.1
    if not np.isfinite(span).all() or np.any(span>np.finfo(np.float32).max):raise ValueError('position_target_float32_overflow')
    return pos,features

def chunk(source,positions,quaternions,interval_open_commands,current_features,start,
          position_divisor=POSITION_DIVISOR):
    p=np.asarray(positions,dtype=np.float64)
    planar=source=='Language Table';width=2 if planar else 3
    if p.ndim!=2 or p.shape[1]!=width or not np.isfinite(p).all():
        raise ValueError('Finite recorded positions with explicit observed dimensions required')
    if not math.isfinite(position_divisor) or position_divisor<=0:raise ValueError('Positive recorded-unit divisor required')
    meta=layout(source,start,len(p));count=meta['valid_targets']
    if not count:raise ValueError('No valid common-grid future target')
    features=np.asarray(current_features,dtype=np.float32)
    if features.shape!=(len(p),2) or not np.isfinite(features).all():raise ValueError('Finite per-row command/availability features required')
    allowed=((features[:,1]==0)&(features[:,0]==0))|((features[:,1]==1)&np.isin(features[:,0],[-1.,1.]))
    if not allowed.all():raise ValueError('Invalid current command/availability features')
    left=np.asarray(meta['left_rows'][:count]);right=np.asarray(meta['right_rows'][:count])
    alpha=np.asarray(meta['right_weights'][:count])
    target_position=(1-alpha[:,None])*p[left]+alpha[:,None]*p[right]
    target=np.zeros((HORIZON,8),np.float32);target[:,6]=1.;target[:,7]=1.
    mask=np.zeros((HORIZON,8),np.float32)
    target[:count,:width]=((target_position-p[start])/position_divisor).astype(np.float32)
    if planar:
        if quaternions is not None or interval_open_commands is not None or np.any(features):
            raise ValueError('Planar source has no measured quaternion/gripper; do not invent them')
        mask[:count,:2]=1.
    else:
        q=np.asarray(quaternions,dtype=np.float64)
        if q.shape!=(len(p),4):raise ValueError('Aligned recorded orientations required')
        command=np.asarray(interval_open_commands,dtype=np.float32)
        if command.shape!=(len(p)-1,) or not np.isin(command,[-1.,1.]).all():
            raise ValueError('One binary absolute open-positive command per valid source interval required')
        target_q=slerp(q[left],q[right],alpha)
        target[:count,3:7]=relative_left(target_q,q[start]).astype(np.float32)
        target[:count,7]=command[np.asarray(meta['command_rows'][:count])]
        mask[:count]=1.
    target[count:]=target[count-1]
    if not np.isfinite(target).all():raise ValueError('Nonfinite resampled target; no repair or clipping')
    return {'actions':target,'supervision_mask':mask,'current_features':features[start].copy(),'layout':meta}

class NominalOXEDataset(Dataset):
    def __init__(self,data_dir,target_directory,source_map=None,*,partition='train'):
        self.data_dir=Path(data_dir).resolve()
        self.store=NominalTargetStore(target_directory,partition=partition)
        self.partition=partition
        self.nominal_target_binding=dict(self.store.binding)
        self.target_manifest_sha256=file_sha(self.store.root/'manifest.json')
        self.chunk_size=16;self.stride=4;self.min_trajectory_steps=10
        self.bcz_target='reached';self.bcz_current_gripper=self.bridge_current_gripper='binary'
        self.bridge_gripper_policy='reverse_scan_valid_steps_v2';self.rt1_gripper_policy='relative_scan_v2'
        self.bcz_reached_gripper_policy='preceding_command_v2';self.oxe_command_input=True
        self.action_frame='source_cartesian';self.action_representation=SOURCE_REPRESENTATION
        self.language_table_groups_sha256=None;self.bridge_episode_selection=[]
        self.oxe_window_manifest=None
        self.frozen_nominal_splits={key:list(range(len(self.store))) if key==partition else [] for key in ('train','validation','test')}
        paths={};sizes={}
        if source_map is not None:
            mapping=json.loads(Path(source_map).read_text(encoding='utf-8'))
            if mapping.get('format')!='oxe-nominal-source-locations-v1':raise ValueError('Explicit nominal source location map required')
            for r in mapping['files']:
                if r['relative_file'] in paths:raise ValueError('Duplicate nominal source location')
                paths[r['relative_file']]=Path(r['path']).resolve();sizes[r['relative_file']]=r['bytes']
        used={e['stage_relative_path'] for e in self.store.episodes}
        self.files={}
        for relative in sorted(used):
            logical=PurePosixPath(relative)
            if logical.is_absolute() or '..' in logical.parts or ':' in relative:
                raise ValueError('Source location escapes its logical root')
            path=paths.get(relative) if source_map is not None else (self.data_dir/relative).resolve()
            if path is None or (source_map is None and self.data_dir not in path.parents):
                raise ValueError('Source file absent from explicit map/root: '+relative)
            if not path.is_file() or (relative in sizes and path.stat().st_size!=sizes[relative]):
                raise ValueError('Source file missing or size changed: '+str(path))
            self.files[relative]=path
        self.samples=[];self.source_counts=Counter();self.tfrecord_episode_counts=Counter()
        for e in self.store.episodes:self.tfrecord_episode_counts[SOURCE_SCHEMAS[e['source']]]+=1
        for wi,(ei,start,_) in enumerate(self.store.windows):
            e=self.store.episodes[int(ei)];schema=SOURCE_SCHEMAS[e['source']]
            self.samples.append({'source':schema,'file_path':str(self.files[e['stage_relative_path']]),
                'record_index':e['record_index'],'start_index':int(start),'trajectory_steps':e['steps'],
                'payload_sha256':e['payload_sha256'],'nominal_window_index':wi})
            self.source_counts[schema]+=1
        self.original_text={}
        text_file='training_original_instructions.jsonl' if partition=='train' else 'validation_original_instructions.jsonl'
        with (self.store.root/text_file).open(encoding='utf-8') as stream:
            for line in stream:
                row=json.loads(line);wi=row['window_index']
                if wi in self.original_text or not 0<=wi<len(self.store):raise ValueError('Duplicate/invalid original text row')
                self.original_text[wi]=row['instruction']
        if set(self.original_text)!=set(range(len(self.store))):raise ValueError('Original text coverage differs')
        self.record_integrity_contract={'kind':'every_used_record_payload_sha256_before_decode',
            'expected_all_role_payload_identities_bound_by_manifest':True,'partition':partition,
            'target_manifest_sha256':self.target_manifest_sha256,
            'whole_container_sha256_claimed':False,
            'source_files':{relative:path.stat().st_size for relative,path in self.files.items()}}

    def __len__(self):return len(self.store)

    def group_key(self,index):return self.store.group_key(index)

    def __getitem__(self,index):
        import tensorflow as tf
        ei,start,_,e,_=self.store._row(index)
        with self.files[e['stage_relative_path']].open('rb') as f:
            f.seek(e['payload_offset']);raw=f.read(e['payload_bytes'])
        if len(raw)!=e['payload_bytes'] or hashlib.sha256(raw).hexdigest()!=e['payload_sha256']:
            raise ValueError('Nominal image/instruction source payload changed: '+e['episode_key'])
        feature=tf.train.Example.FromString(raw).features.feature
        source=e['source']
        image_key={'Bridge':'steps/observation/image_0','Language Table':'steps/observation/rgb',
